    {"id":12801,"before_hash":"fc300b12fd1b43ad6238043a4e4eb634","prompt":"광복절 아침, 기념 방송을 둘이 골라 본다면 어떤 자료가 궁금한가요?","samples":["당시 라디오에 어떤 소리가 담겼는지요.","먼 곳에 남아 있던 편지가 어떻게 돌아왔는지요.","한 장의 사진을 복원한 과정이 궁금해요."]},
    {"id":12802,"before_hash":"0c6bcc28b4a897f264830e36fe399ead","prompt":"광복절에 둘이 읽은 기록을 잊지 않으려면, 어떻게 간직하고 싶나요?","samples":["마음에 남은 문장을 손으로 옮겨 적을래요.","다시 읽을 수 있게 자료 이름을 남길래요.","궁금했던 단어의 뜻을 찾아 기록 옆에 적을래요."]},
    {"id":12902,"before_hash":"6eeb3e5cd15ccbe5d30232390a982ce2","prompt":"현충일에 읽은 글에서 오래 기억하고 싶은 부분은 어떻게 남겨 둘까요?","samples":["일기에 이름과 날짜를 적어 둘래요.","다시 찾아보게 자료 제목을 적어요.","마음이 머문 한 구절을 옮겨 쓸래요."]}
  ]$copy_json$::jsonb;
begin
  -- Lock only the reviewed rows before checking their contents.
  perform q.id
  from pajang_private.question_catalog q
  join jsonb_to_recordset(patches) as p(id integer) on p.id = q.id
  for update of q;

  if exists (
    select 1
    from jsonb_to_recordset(patches) as p(id integer, before_hash text, prompt text, samples text[])
    left join pajang_private.question_catalog q on q.id = p.id
    where q.id is null
      or (
        md5(q.prompt || chr(31) || array_to_string(q.samples, chr(31))) is distinct from p.before_hash
        and (q.prompt is distinct from p.prompt or q.samples is distinct from p.samples)
      )
  ) then
    raise exception 'Pajang question catalog changed since copy review; inspect the affected rows before applying';
  end if;

  update pajang_private.question_catalog q
  set prompt = p.prompt, samples = p.samples
  from jsonb_to_recordset(patches) as p(id integer, prompt text, samples text[])
  where q.id = p.id
    and (q.prompt is distinct from p.prompt or q.samples is distinct from p.samples);

  if exists (
    select 1
    from jsonb_to_recordset(patches) as p(id integer, prompt text, samples text[])
    left join pajang_private.question_catalog q on q.id = p.id
    where q.id is null or q.prompt is distinct from p.prompt or q.samples is distinct from p.samples
  ) then
    raise exception 'Pajang question copy verification failed';
  end if;
end;
$pajang_copy$;
